3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
5	import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;
6	
7	/**
8	 * Second step of {@code POST /api/owners}: normalises the telephone by stripping every
9	 * non-digit character, then requires exactly 10 digits. The cleaned 10-digit value is written
10	 * back onto the (shared) request DTO so it is stored and returned as {@code telephone}; anything
11	 * that is not exactly 10 digits after stripping is rejected 400 via {@link InvalidTelephoneException}.
12	 */
13	public class NormalizeOwnerTelephone {
14	
15	    public void service(@Val OwnerFieldsDto request) throws InvalidTelephoneException {
16	        String digits = request.getTelephone().replaceAll("\\D", "");
17	        if (digits.length() != 10) {
18	            throw new InvalidTelephoneException(request.getTelephone());
19	        }
20	        request.setTelephone(digits);
21	    }
22	}
