1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.DuplicateTelephoneException;
8	
9	/**
10	 * Third step of {@code POST /api/owners}: rejects the request 409 when its (already normalised)
11	 * telephone matches the normalised telephone of any existing owner. Runs after
12	 * {@link NormalizeOwnerTelephone} so both sides are compared as bare digits, and before
13	 * {@link BuildOwner} so no owner is persisted on conflict.
14	 */
15	public class RequireUniqueTelephone {
16	
17	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
18	            throws DuplicateTelephoneException {
19	        String telephone = request.getTelephone();
20	        for (Owner existing : ownerRepository.findAll()) {
21	            if (telephone.equals(normalize(existing.getTelephone()))) {
22	                throw new DuplicateTelephoneException(telephone);
23	            }
24	        }
25	    }
26	
27	    private static String normalize(String telephone) {
28	        return telephone == null ? null : telephone.replaceAll("\\D", "");
29	    }
30	}
